captions.css:
@font-face { font-family: 'Lilita One'; src: url('assets/fonts/LilitaOne-Regular.woff2') format('woff2'); font-weight: 400; }
    .inner { font-family: 'Lilita One', sans-serif; font-weight: 400; line-height: 1.12; letter-spacing: .01em; }
    .inner .bar .w { margin: 0 .07em; }
    .inner .bar { border-radius: .55em; padding: .04em .36em .1em; box-shadow: 0 8px 0 rgba(0,0,0,.25); }
    .inner .w { white-space: nowrap; color: #fff; }
    .inner .w.k-y, .inner .w.k-g, .inner .w.k-p { color: #ffe14a; }
